<form method="get" class="date-filter" style="padding:0 18px 14px;justify-content:flex-end"><span class="dashboard-date-filter-label"><span class="material-symbols-outlined">filter_alt</span>Incident date</span><input type="date" name="date" value="<?=e($filterDate)?>"><button class="gw-btn secondary">Filter</button><?php if($filterDate):?><a class="gw-btn secondary" href="<?=e(url('/modules/health_safety/index.php'))?>#incident-reports">Clear</a><?php endif;?><?php if($showAllIncidents):?><a class="gw-btn secondary" href="<?=e(url('/modules/health_safety/index.php'.($filterDate?'?date='.rawurlencode($filterDate):'')))?>#incident-reports">Show latest 5</a><?php else:?><a class="gw-btn primary" href="<?=e(url('/modules/health_safety/index.php?incident_all=1'.($filterDate?'&date='.rawurlencode($filterDate):'')))?>#incident-reports">See all safety incident reports</a><?php endif;?></form>
