<tr>
<td><strong><?=e($r['title'])?></strong><br><small>Report #<?=e((string)$r['id'])?></small><br><small>Submitted: <?=e($r['created_at']??'—')?></small></td>
<td><?=e($r['incident_date'])?><br><small><?=e($r['incident_time']??'')?></small></td>
<td><?=e($r['location']??'—')?></td>
<td><?=e($r['employee_name'])?><br><small><?=e($r['employee_id']??'')?></small></td>
<td><?=e($r['incident_type']??'—')?><br><strong><?=e($r['severity'])?></strong></td>
<td><?=e($r['status'])?></td>
<td><?=e($r['description']??'—')?><?php if(!empty($r['immediate_action'])):?><br><small><strong>Immediate action:</strong> <?=e($r['immediate_action'])?></small><?php endif;?><?php if(!empty($r['corrective_action'])):?><br><small><strong>Corrective action:</strong> <?=e($r['corrective_action'])?></small><?php endif;?></td>
<td><?php if($files): foreach($files as $fileIndex=>$file): if(is_string($file) && preg_match('#^storage/health_safety/incidents/[a-f0-9]{32}\.(jpg|png|webp|pdf)$#',$file)): ?><a href="<?=e(url('/modules/health_safety/incident_attachment.php?report_id='.(int)$r['id'].'&file='.(int)$fileIndex))?>" target="_blank" rel="noopener">View file <?=e((string)($fileIndex+1))?></a><br><?php endif; endforeach; else: ?>—<?php endif;?></td>
<td class="incident-actions-cell"><div class="incident-actions"><a class="gw-btn secondary" href="<?=e(url('/modules/health_safety/view_incident_report.php?id='.(int)$r['id']))?>">View</a><a class="gw-btn secondary" href="<?=e(url('/modules/health_safety/edit_incident_report.php?id='.(int)$r['id']))?>">Edit</a><?php if((current_user()['role']??'')==='Administrator'): ?><form method="post" onsubmit="return confirm('Delete this incident report? It will be moved to Archive.');"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_incident"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="gw-btn danger" type="submit">Delete</button></form><?php endif; ?></div></td>
</tr>
